@file:OptIn(ExperimentalForeignApi::class)

package io.github.kingg22.godot.test.inheritance

import io.github.kingg22.godot.api.builtin.toStringName
import io.github.kingg22.godot.api.core.RefCounted
import io.github.kingg22.godot.api.singleton.ClassDB
import io.github.kingg22.godot.internal.binding.ObjectBinding
import kotlinx.cinterop.ExperimentalForeignApi
import kotlin.test.Test
import kotlin.test.assertTrue

/**
 * Inheritance matrix: every engine class the generated API lets a user extend has a `@Godot` subclass
 * `Matrix<Parent>` (`InheritanceMatrix.kt`, generated by `mi-juego-prueba/tools/generate_inheritance_matrix.py`),
 * registered by the KSP processor like any user class. This checks that Godot registered each one with the right
 * parent, and that `ClassDB.instantiate` builds it through the KSP factory: the object is the Kotlin `Matrix<Parent>`
 * instance and is still a `<Parent>` for the engine.
 *
 * The known failures are separate tests, red on purpose until fixed:
 * - the classes the generator renames in Kotlin (`Object` -> `GodotObject`, `Range` -> `GodotRange`, ...) are
 *   registered with the Kotlin name as parent, which Godot does not know (#239);
 * - editor classes do not exist yet when kogot registers its classes (#241).
 *
 * What Kotlin refuses at compile time (abstract, final and singleton parents) is not part of the matrix; see
 * `docs/inheritance-matrix.md`.
 */
class InheritanceTest {
    @Test
    fun subclassesAreRegisteredWithTheirEngineParent() {
        val wrong = SUPPORTED.mapNotNull(::registrationProblem)
        assertTrue(wrong.isEmpty(), "${wrong.size} wrong: ${wrong.take(MAX_LISTED)}")
    }

    @Test
    fun subclassesAreInstantiatedThroughTheKspFactory() {
        val wrong = SUPPORTED.filterNot { it in NOT_INSTANTIATED }.mapNotNull(::instantiationProblem)
        assertTrue(wrong.isEmpty(), "${wrong.size} wrong: ${wrong.take(MAX_LISTED)}")
    }

    /** Red until #239: the parent is registered with the Kotlin name, not the engine name. */
    @Test
    fun subclassesOfClassesRenamedInKotlinAreRegistered_239() {
        val wrong = INHERITANCE_MATRIX_RENAMED.mapNotNull(::registrationProblem)
        assertTrue(wrong.isEmpty(), "${wrong.size} wrong: $wrong")
    }

    /** Red until #241: editor classes are registered by Godot after kogot registers its own. */
    @Test
    fun subclassesOfEditorClassesAreRegistered_241() {
        val wrong = INHERITANCE_MATRIX_EDITOR.mapNotNull(::registrationProblem)
        assertTrue(wrong.isEmpty(), "${wrong.size} wrong: $wrong")
    }

    private fun registrationProblem(parent: String): String? {
        val className = "$CLASS_PREFIX$parent"
        val exists = className.toStringName().use { ClassDB.instance.classExists(it) }
        if (!exists) return "$className not registered"
        val actual = className.toStringName().use { name ->
            ClassDB.instance.getParentClass(name).use { it.toString() }
        }
        return if (actual == parent) null else "$className has parent $actual"
    }

    private fun instantiationProblem(parent: String): String? {
        val className = "$CLASS_PREFIX$parent"
        val instance = className.toStringName().use { name ->
            ClassDB.instance.instantiate(name).use { it.toObjectOrNull() }
        } ?: return "$className: instantiate gave null"
        try {
            val kotlinClass = instance::class.simpleName
            if (kotlinClass != className) return "$className: the object is a $kotlinClass, not the KSP instance"
            val isParent = parent.toStringName().use { instance.isClass(it) }
            if (!isParent) return "$className: the engine does not see it as a $parent"
            return null
        } finally {
            // A RefCounted goes away with its last reference; any other object must be freed by its owner, us.
            if (instance !is RefCounted) ObjectBinding.destroyRaw(instance.rawPtr)
        }
    }

    private companion object {
        const val CLASS_PREFIX = "Matrix"
        const val MAX_LISTED = 20

        /** The parents that are supposed to work today: the matrix without the known failures. */
        val SUPPORTED = INHERITANCE_MATRIX_PARENTS -
            INHERITANCE_MATRIX_RENAMED.toSet() -
            INHERITANCE_MATRIX_EDITOR.toSet()

        /**
         * Registered but not instantiated: constructing one of these installs it as the engine's physics or text
         * server singleton, and freeing it leaves that singleton dangling. The next physics node then crashes the
         * engine (seen with `PinJoint2D` after `PhysicsServer2DExtension`, with or without kogot).
         */
        val NOT_INSTANTIATED = setOf("PhysicsServer2DExtension", "PhysicsServer3DExtension", "TextServerExtension")
    }
}
